const XLSX = require('xlsx');

// Récupérer le fichier Excel binaire en entrée
const binaryData = items[0].binary.data;
const wb = XLSX.read(binaryData, { type: 'buffer', cellDates: true });

// Récupérer les données des nœuds précédents
const getDealsData = $node['Get Deals'].json;
const stageName = $node['Manual Trigger'].json.stageName;
const prospects = getDealsData.map(deal => deal.title);
const startDate = new Date(getDealsData[0].expected_close_date);

// Extraire le numéro de cohorte du nom du stage
const cohortNumber = stageName.match(/\d+/)[0];

// 1. Identifier le dernier onglet Fact.XXXXX
const factSheets = wb.SheetNames.filter(name => /^Fact\.\s20\d{5}$/.test(name));
if (factSheets.length === 0) throw new Error('Aucun onglet Facture trouvé');

// Trier par numéro décroissant
factSheets.sort((a, b) => {
  const numA = parseInt(a.split(' ')[1].substring(4));
  const numB = parseInt(b.split(' ')[1].substring(4));
  return numB - numA;
});
const lastSheetName = factSheets[0];
const lastSheet = wb.Sheets[lastSheetName];

// Extraire le dernier numéro de facture
const lastInvoiceNumber = parseInt(lastSheetName.split(' ')[1].substring(4));
const nextInvoiceNumber = lastInvoiceNumber + 1;
const year = new Date().getFullYear();
const nextInvoiceNumberPadded = String(nextInvoiceNumber).padStart(3, '0');
const newInvoiceNumber = `${year}${nextInvoiceNumberPadded}`;
const newSheetName = `Fact. ${newInvoiceNumber}`;

// 2. Vérifier les doublons dans Registre
const registreSheet = wb.Sheets['Registre'];
if (!registreSheet) throw new Error('Onglet Registre introuvable');

const registreData = XLSX.utils.sheet_to_json(registreSheet, { header: 1 });
const cohortColIndex = registreData[0].indexOf('Cohorte');
if (cohortColIndex === -1) throw new Error('Colonne Cohorte introuvable');

for (let i = 1; i < registreData.length; i++) {
  if (registreData[i][cohortColIndex] === parseInt(cohortNumber)) {
    throw new Error(`Cohorte ${cohortNumber} déjà facturée`);
  }
}

// 3. Copier le dernier onglet
wb.SheetNames.push(newSheetName);
const newSheet = JSON.parse(JSON.stringify(lastSheet));
wb.Sheets[newSheetName] = newSheet;

// 4. Mettre à jour le nouvel onglet
// - Date de facturation (date démarrage + 1 jour)
const invoiceDate = new Date(startDate);
invoiceDate.setDate(invoiceDate.getDate() + 1);
const formattedDate = invoiceDate.toISOString().split('T')[0].split('-').reverse().join('/');

// - Numéro de facture (cellule B1)
wb.Sheets[newSheetName]['B1'] = { t: 's', v: newInvoiceNumber };

// - Date facturation (cellule B2)
wb.Sheets[newSheetName]['B2'] = { t: 's', v: formattedDate };

// - Numéro cohorte (cellule B3)
wb.Sheets[newSheetName]['B3'] = { t: 'n', v: parseInt(cohortNumber) };

// - Liste des prospects (à partir de A5)
prospects.forEach((prospect, i) => {
  const cell = `A${5 + i}`;
  wb.Sheets[newSheetName][cell] = { t: 's', v: prospect };
});

// 5. Ajouter ligne dans Registre
const newRegRow = [
  year,
  newInvoiceNumber,
  formattedDate,
  '',
  prospects.length * 150,
  '',
  parseInt(cohortNumber)
];
registreData.push(newRegRow);
const newRegSheet = XLSX.utils.aoa_to_sheet(registreData);
wb.Sheets['Registre'] = newRegSheet;

// 6. Exporter le workbook mis à jour
const updatedBinary = XLSX.write(wb, { bookType: 'xlsx', type: 'buffer' });

// 7. Retourner les données pour les nœuds suivants
return [{
  json: {
    invoiceNumber: newInvoiceNumber,
    cohorte: cohortNumber,
    totalAmount: prospects.length * 150,
    prospectsCount: prospects.length,
    sheetName: newSheetName
  },
  binary: {
    data: updatedBinary
  }
}];
